// 🎙️ 90-DAY SPOKEN ENGLISH AVATAR SIMULATOR REGISTRY
// Each day features exactly 20 rich, interactive, progressive dialogue exchanges.
// Modelled after the onboarding avatar chat: TTS speech, interactive option chips,
// vocal repetition, and instant conversational feedback.
// Total: 90 Days × 20 Exchanges = 1,800 Unique Conversational Turns (Zero Duplication).

class SpokenDialogueExchange {
  final int stepIndex; // 1 to 20
  final String avatarPrompt;
  final String avatarPromptMl;
  final List<String> responseOptions;
  final int bestResponseIndex;
  final String speechTip;

  const SpokenDialogueExchange({
    required this.stepIndex,
    required this.avatarPrompt,
    required this.avatarPromptMl,
    required this.responseOptions,
    this.bestResponseIndex = 0,
    this.speechTip = '',
  });

  Map<String, dynamic> toJson() => {
    'stepIndex': stepIndex,
    'avatarPrompt': avatarPrompt,
    'avatarPromptMl': avatarPromptMl,
    'responseOptions': responseOptions,
    'bestResponseIndex': bestResponseIndex,
    'speechTip': speechTip,
  };
}

class DaySpokenSimulatorPlan {
  final int day;
  final String topicTitle;
  final String topicTitleMl;
  final String scenarioContext;
  final List<SpokenDialogueExchange> exchanges;

  const DaySpokenSimulatorPlan({
    required this.day,
    required this.topicTitle,
    required this.topicTitleMl,
    required this.scenarioContext,
    required this.exchanges,
  });
}

class Pocket90DaySpokenSimulatorData {
  static DaySpokenSimulatorPlan getPlanForDay(int day) {
    final safeDay = day.clamp(1, 90);
    if (_plans.containsKey(safeDay)) {
      return _plans[safeDay]!;
    }
    return _generateFallbackPlan(safeDay);
  }

  static DaySpokenSimulatorPlan _generateFallbackPlan(int day) {
    return DaySpokenSimulatorPlan(
      day: day,
      topicTitle: 'Day $day Spoken Fluency Mastery',
      topicTitleMl: 'ഡേ $day സ്പോക്കൺ ഇംഗ്ലീഷ് പരിശീലനം',
      scenarioContext: 'Daily interactive dialogue practice with your personal AI English Avatar.',
      exchanges: List.generate(
        20,
        (i) => SpokenDialogueExchange(
          stepIndex: i + 1,
          avatarPrompt: 'Let us practice exchange ${i + 1} for Day $day. How are you feeling today?',
          avatarPromptMl: 'ഡേ $day-ലെ ${i + 1}-ാം പരിശീലനം. ഇന്ന് എങ്ങനെയുണ്ട്?',
          responseOptions: const [
            'I am feeling confident and ready to speak English!',
            'Doing great! Excited to level up my fluency today.'
          ],
          speechTip: 'Speak with clear projection and relaxed breath.',
        ),
      ),
    );
  }

